const now = new Date();
const br = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dia1111 = br.getMonth() === 10 && br.getDate() === 11 && br.getHours() >= 6; // 11/11: 6h à meia-noite
return [{ json: { hora_num: dia1111 ? 12 : br.getHours(), agora_br: br.toLocaleString('pt-BR') } }];

// Lê as palavras-chave do PERFIL no painel (fonte de verdade). Fallback = lista antiga.
const SECRET = "d9eb7e94067def9f8eb7e64e2b2d28cc93e092c62344a259e76682f9c1327235";
let KW = [];
try {
  const res = await this.helpers.httpRequest({
    method: "GET",
    url: "https://app.buscadorgeek.com.br/api/keywords/collector?slug=ofertas-maternas",
    headers: { "x-ingest-secret": SECRET },
    json: true,
  });
  if (res && Array.isArray(res.keywords)) KW = res.keywords;
} catch (e) {}
if (!KW.length) KW = ["fralda descartável","lenço umedecido","creme assadura","sabonete bebê","bebê conforto","brinquedo infantil","enxoval bebê","monitor bebê","banheira bebê","triciclo infantil","grade cama bebê","quarto bebê","copo infantil","touca bebê","prendedor chupeta","espelho carro bebê","garrafa térmica infantil","estante infantil","protetor solar infantil","chiqueirinho bebê"];
// fralda/lenço (melhor comissão) sorteados em ~35% das rodadas — decisão Bruno 08/Out (lista de keywords intacta)
const PRIOR = KW.filter(w => /fralda|len[cç]o/i.test(w));
const k = (PRIOR.length && Math.random() < 0.35) ? PRIOR[Math.floor(Math.random()*PRIOR.length)] : KW[Math.floor(Math.random()*KW.length)];
return [{ json: { keyword: k, row_number: 1 } }];

const data = $input.first().json;
const tokenResp = await this.helpers.httpRequest({
  method: 'POST', url: 'https://api.amazon.com/auth/o2/token',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ grant_type: 'client_credentials', client_id: data.amazon_access_key, client_secret: data.amazon_secret_key, scope: 'creatorsapi::default' }),
  returnFullResponse: false, json: false
});
const token = typeof tokenResp === 'string' ? JSON.parse(tokenResp) : tokenResp;
return [{ json: { access_token: token.access_token, partner_tag: data.amazon_partner_tag, keyword: data.keyword, keyword_row: data.keyword_row } }];

// 26/Out: páginas 1-3 com ordem fixa esgotaram (tudo já cadastrado, 16h sem Amazon nova) → página 1-8 + ordem sorteada
const ORDENS = ["Relevance", "Featured", "NewestArrivals", "Price:LowToHigh", "AvgCustomerReviews"];
const data = $input.first().json;
const searchResp = await this.helpers.httpRequest({
  method: 'POST', url: 'https://creatorsapi.amazon/catalog/v1/searchItems',
  headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + data.access_token, 'x-marketplace': 'www.amazon.com.br' },
  body: JSON.stringify({ itemPage: 1 + Math.floor(Math.random() * 8), sortBy: ORDENS[Math.floor(Math.random() * ORDENS.length)], keywords: data.keyword, partnerTag: data.partner_tag, marketplace: 'www.amazon.com.br',
    resources: ['itemInfo.title','offersV2.listings.price','offersV2.listings.availability','offersV2.listings.condition','offersV2.listings.dealDetails','images.primary.medium','customerReviews.starRating','customerReviews.count'] }),
  returnFullResponse: false, json: false
});
const result = typeof searchResp === 'string' ? JSON.parse(searchResp) : searchResp;
return [{ json: { ...result, _keyword: data.keyword, _keyword_row: data.keyword_row } }];

const response = $input.first().json;
const keyword = response._keyword;
const keywordRow = response._keyword_row;
if (response.errors || !response.searchResult || !response.searchResult.items) {
  return [{ json: { error: true, message: response.errors ? JSON.stringify(response.errors) : 'No searchResult', keyword, keyword_row: keywordRow, total_filtrado: 0, produtos: [] } }];
}
const items = response.searchResult.items || [];
const filtered = [];
for (const item of items) {
  const asin = item.asin;
  const title = item.itemInfo?.title?.displayValue || '';
  const detailUrl = item.detailPageURL || '';
  const imageUrl = item.images?.primary?.medium?.url || '';
  const listings = item.offersV2?.listings || [];
  const buyBox = listings.find(l => l.isBuyBoxWinner) || listings[0];
  if (!buyBox || !buyBox.price?.money?.amount) continue;
  const priceAmount = buyBox.price.money.amount;
  const originalPrice = buyBox.price.savingBasis?.money?.amount || 0;
  const savingsPct = originalPrice > 0 ? Math.round(((originalPrice - priceAmount) / originalPrice) * 100) : 0;
  const rating = item.customerReviews?.starRating?.value || 0;
  const reviewCount = item.customerReviews?.count || 0;
  if (priceAmount <= 0) continue;
  if (reviewCount > 0 && rating < 4.0) continue;
  filtered.push({ asin, title, detail_url: detailUrl, image_url: imageUrl, price: priceAmount, original_price: originalPrice, savings_pct: savingsPct, rating, review_count: reviewCount, keyword });
}
return [{ json: { error: false, keyword, keyword_row: keywordRow, total_api: items.length, total_filtrado: filtered.length, produtos: filtered } }];

const items=$input.all(); const out=[];
function num(v){ const n=parseFloat(v); return isNaN(n)?null:n; }
function bigImg(u){ if(!(typeof u==='string'&&u.indexOf('http')===0)) return null; return u.replace(/\._(S[LXY]\d+|SS\d+|AC_[^.]*)_\./,'._SL500_.'); }
for(const it of items){
  const produtos=it.json.produtos||[];
  for(const p of produtos){
    const url=p.detail_url;
    if(!url || String(url).indexOf('http')!==0) continue;
    const cur=num(p.price), orig=num(p.original_price);
    out.push({ json:{
      source:'auto', source_ref:'amazon_'+p.asin, platform:'amazon',
      url, affiliate_url:url,
      title:((p.title||'')+'').slice(0,500)||null,
      image_url:bigImg(p.image_url),
      price_current:cur, price_original:(orig&&cur&&orig>cur)?orig:null,
      discount_pct:(p.savings_pct&&p.savings_pct>0)?p.savings_pct:null,
      perfil:'ofertas-maternas'
    }});
  }
}
return out;
